import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Conseguenze del teorema della permanenza del segno","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/q_successioni-e-serie/qc/qcjc.md","filePath":"lezioni/q_successioni-e-serie/qc/qcjc.md"}`),a={name:`lezioni/q_successioni-e-serie/qc/qcjc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="conseguenze-del-teorema-della-permanenza-del-segno" tabindex="-1">Conseguenze del teorema della permanenza del segno <a class="header-anchor" href="#conseguenze-del-teorema-della-permanenza-del-segno" aria-label="Permalink to “Conseguenze del teorema della permanenza del segno”">​</a></h1><p>Come prima conseguenza possiamo dire che vale</p><blockquote><p><strong>Se una successione numerica reale ammette limite maggiore di un numero reale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> allora, da un certo termine in poi, tutti i suoi termini sono maggiori di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span></strong></p></blockquote><p>Facendo riferimento alla rappresentazione cartesiana è come se, rappresentato il teorema della permanenza del segno, ci mettessimo una retta orizzontale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>=</mo><mi>c</mi></mrow><annotation encoding="application/x-tex">y = c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>, vedi ad esempio i primi grafici di questa pagina: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> potrebbe essere il bordo non marcato della striscia grigio-azzurra</p><p>Abbiamo due possibilità:</p><ul><li>la successione è decrescente: allora si trova più in alto di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> e quindi tutti i suoi termini sono maggiori di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span></li><li>la successione è crescente: allora ha i primi termini minori di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>, un termine che, se esiste, è uguale a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>, e quindi tutti i suoi termini successivi che sono maggiori di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span></li></ul><p>e vale, analogamente:</p><blockquote><p><strong>Se una successione numerica reale ammette limite minore di un numero reale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> allora, da un certo termine in poi, tutti i suoi termini sono minori di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span></strong></p></blockquote><hr><p>Il teorema della permanenza del segno ci permette anche di enunciare il seguente teorema utile per il confronto fra successioni</p><blockquote><p><strong>Se una successione numerica reale ammette limite ed ha tutti i termini non negativi allora essa converge ad un numero positivo o nullo</strong></p></blockquote><p>logicamente vale anche</p><blockquote><p><strong>Se una successione numerica reale ammette limite ed ha tutti i termini non positivi allora essa converge ad un numero negativo o nullo</strong></p></blockquote><p>Infatti per il teorema della permanenza del segno i termini più &quot;avanzati&quot; della successione hanno lo stesso segno del limite e anche il limite deve avere lo stesso segno di tali termini; fa eccezione una successione che sia convergente a zero, perché mentre tutti i termini &quot;avanzati&quot; della successione sono positivi (o negativi) il limite invece sarà zero che, notoriamente, non ha segno: da qui la precisazione &quot;positivo o nullo&quot; (&quot;negativo o nullo&quot;).</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};